    "#9 Average trip by duration\n",
    "plt.figure(figsize=(8, 5))\n",
    "ax = sns.barplot(x='Route', y='Trip_Duration_Minutes', data=df, estimator='mean', palette='Oranges')\n",
    "plt.title(\"Average Trip Duration by Route\", fontsize=14, fontweight='bold')\n",
